SELECT * FROM users;
SELECT (SELECT COUNT(*) FROM users) AS users, (SELECT COUNT(*) FROM posts) AS posts;

CREATE TABLE signups (member TEXT, club TEXT, club_room TEXT);
INSERT INTO signups VALUES ('Ana', 'Chess', 'A10'), ('Ben', 'Chess', 'A10'), ('Chen', 'Robotics', 'C3'), ('Dara', 'Chess', 'A10');
UPDATE signups SET club_room = 'B12' WHERE member = 'Ana';
SELECT DISTINCT club, club_room FROM signups ORDER BY club, club_room;
CREATE TABLE clubs (id INTEGER PRIMARY KEY, name TEXT UNIQUE, room TEXT);
CREATE TABLE members (id INTEGER PRIMARY KEY, name TEXT, club_id INTEGER REFERENCES clubs(id));
INSERT INTO clubs (name, room) SELECT DISTINCT club, 'A10' FROM signups WHERE club = 'Chess';
INSERT INTO clubs (name, room) VALUES ('Robotics', 'C3');
INSERT INTO members (name, club_id) SELECT s.member, c.id FROM signups s JOIN clubs c ON c.name = s.club;
UPDATE clubs SET room = 'B12' WHERE name = 'Chess';
SELECT m.name AS member, c.name AS club, c.room
FROM members m JOIN clubs c ON c.id = m.club_id
ORDER BY m.name;

CREATE TABLE accounts (id INTEGER PRIMARY KEY, email TEXT, balance INTEGER);
